FILES={"src/lib/bim.ts": "", "src/lib/__tests__/bim.test.ts": "", "src/components/Model3DViewer.tsx": ""}
EDITS=[["src/app/projects/[id]/page.tsx", "import-bim", "aW1wb3J0IHsgaXNCaW1PcjNEIH0gZnJvbSAnQC9saWIvYmltJw==", "aW1wb3J0IHsgaXNDYWRGaWxlIH0gZnJvbSAnQC9saWIvY2FkJzs=", "aW1wb3J0IHsgaXNDYWRGaWxlIH0gZnJvbSAnQC9saWIvY2FkJzsKaW1wb3J0IHsgaXNCaW1PcjNEIH0gZnJvbSAnQC9saWIvYmltJzs="], ["src/app/projects/[id]/page.tsx", "dynamic-3d", "aW1wb3J0KCdAL2NvbXBvbmVudHMvTW9kZWwzRFZpZXdlcicp", "Y29uc3QgQ2FkVmlld2VyID0gZHluYW1pYygoKSA9PiBpbXBvcnQoJ0AvY29tcG9uZW50cy9DYWRWaWV3ZXInKSwgeyBzc3I6IGZhbHNlIH0pOw==", "Y29uc3QgQ2FkVmlld2VyID0gZHluYW1pYygoKSA9PiBpbXBvcnQoJ0AvY29tcG9uZW50cy9DYWRWaWV3ZXInKSwgeyBzc3I6IGZhbHNlIH0pOwpjb25zdCBNb2RlbDNEVmlld2VyID0gZHluYW1pYygoKSA9PiBpbXBvcnQoJ0AvY29tcG9uZW50cy9Nb2RlbDNEVmlld2VyJyksIHsgc3NyOiBmYWxzZSB9KTs="], ["src/app/projects/[id]/page.tsx", "state-3d", "Y29uc3QgW21vZGVsM2RGaWxlLCBzZXRNb2RlbDNkRmlsZV0=", "ICBjb25zdCBbY2FkRmlsZSwgc2V0Q2FkRmlsZV0gPSB1c2VTdGF0ZTx7IGlkOiBzdHJpbmc7IG5hbWU6IHN0cmluZyB9IHwgbnVsbD4obnVsbCk7", "ICBjb25zdCBbY2FkRmlsZSwgc2V0Q2FkRmlsZV0gPSB1c2VTdGF0ZTx7IGlkOiBzdHJpbmc7IG5hbWU6IHN0cmluZyB9IHwgbnVsbD4obnVsbCk7CiAgY29uc3QgW21vZGVsM2RGaWxlLCBzZXRNb2RlbDNkRmlsZV0gPSB1c2VTdGF0ZTx7IGlkOiBzdHJpbmc7IG5hbWU6IHN0cmluZyB9IHwgbnVsbD4obnVsbCk7"], ["src/app/projects/[id]/page.tsx", "openfile-3d", "aXNCaW1PcjNEKHRhcmdldC5uYW1lLCB0YXJnZXQuZmlsZVR5cGUp", "ICAgIGlmICh0YXJnZXQgJiYgaXNDYWRGaWxlKHRhcmdldC5uYW1lLCB0YXJnZXQuZmlsZVR5cGUpKSB7", "ICAgIGlmICh0YXJnZXQgJiYgaXNCaW1PcjNEKHRhcmdldC5uYW1lLCB0YXJnZXQuZmlsZVR5cGUpKSB7CiAgICAgIHNldE1vZGVsM2RGaWxlKHsgaWQ6IGZpbGVJZCwgbmFtZTogdGFyZ2V0Lm5hbWUgfSk7CiAgICAgIHJldHVybjsKICAgIH0KICAgIGlmICh0YXJnZXQgJiYgaXNDYWRGaWxlKHRhcmdldC5uYW1lLCB0YXJnZXQuZmlsZVR5cGUpKSB7"], ["src/app/projects/[id]/page.tsx", "render-3d", "bW9kZWwzZEZpbGUgJiYgKA==", "ICAgICAge2NhZEZpbGUgJiYgKAogICAgICAgIDxDYWRWaWV3ZXIgZmlsZUlkPXtjYWRGaWxlLmlkfSBmaWxlTmFtZT17Y2FkRmlsZS5uYW1lfSB0b2tlbj17Z2V0VG9rZW4oKX0gY2FuQW5ub3RhdGU9e2Nhbk1hbmFnZSB8fCBjYW5VcGxvYWR9IG9uQ2xvc2U9eygpID0+IHNldENhZEZpbGUobnVsbCl9IC8+CiAgICAgICl9", ""]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:]); print("== Bilnov M3 - viewer IFC/BIM + 3D + AR ==")
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
    cache={}
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src: print("  = deja",name); cache[p]=src; continue
        if old not in src: print("!! ANCRE KO:",name); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; print("  ~ patche",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    # dependance web-ifc
    pkgp=os.path.join(root,'package.json'); pkg=json.load(open(pkgp,encoding='utf-8'))
    pkg.setdefault('dependencies',{})
    if 'web-ifc' not in pkg['dependencies']:
        pkg['dependencies']['web-ifc']='0.0.57'
        json.dump(pkg,open(pkgp,'w',encoding='utf-8'),indent=2,ensure_ascii=False); open(pkgp,'a').write('\n')
        print("  ~ package.json : + web-ifc")
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Viewer IFC/BIM + 3D + AR applique. Aucun git push. (Tester en runtime: ouvrir un fichier IFC/GLB.)")
if __name__=='__main__': main()
